const upsertAPIResource = `-- name: UpsertAPIResource :exec
INSERT INTO raiwall_api_resources (
    id, app_id, method, path_pattern, content_type, hit_count, last_seen, created_at
) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(app_id, method, path_pattern) DO UPDATE SET
    hit_count = raiwall_api_resources.hit_count + excluded.hit_count,
    content_type = CASE WHEN excluded.content_type != '' THEN excluded.content_type ELSE raiwall_api_resources.content_type END,
    last_seen = excluded.last_seen
`

type UpsertAPIResourceParams struct {
	ID          string
	AppID       string
	Method      string
	PathPattern string
	ContentType string
	HitCount    int64
	LastSeen    time.Time
	CreatedAt   time.Time
}

func (q *Queries) UpsertAPIResource(ctx context.Context, arg UpsertAPIResourceParams) error {
	_, err := q.db.ExecContext(ctx, upsertAPIResource,
		arg.ID,
		arg.AppID,
		arg.Method,
		arg.PathPattern,
		arg.ContentType,
		arg.HitCount,
		arg.LastSeen,
		arg.CreatedAt,
	)
	return err
}
